if (path_in_iso.empty()) { FUZZ_BAIL(); }

int fd = isofs_Open(path_in_iso.c_str());
if (fd < 0) { FUZZ_BAIL(); }

// Wrap the integer fd in a small heap object so the fuzzer runtime can persist it across stubs.
// We use a u8* (matches ptr_type) as an opaque handle and attach metadata via attributes.
u8 *fd_obj = new u8[1];
FUZZ_SET_ATTR_INT(fd_obj, "fd", fd);
FUZZ_SET_ATTR_INT(fd_obj, "open", 1);

// Track global open count for safe reset/reinit coordination
int open_fd_count = FUZZ_GET_ATTR_INT_GLOBAL("isofs_open_fd_count");
FUZZ_SET_ATTR_INT_GLOBAL("isofs_open_fd_count", open_fd_count + 1);

// Validate that the fd object is marked open
int is_open = FUZZ_GET_ATTR_INT(fd_obj, "open");
int fd = FUZZ_GET_ATTR_INT(fd_obj, "fd");
if (!is_open) { FUZZ_BAIL(); }

int rc = isofs_Close(fd);
if (rc < 0) { FUZZ_BAIL(); }

// Mark closed and update global count; drop the object by not returning it
FUZZ_SET_ATTR_INT(fd_obj, "open", 0);
int open_fd_count = FUZZ_GET_ATTR_INT_GLOBAL("isofs_open_fd_count");
FUZZ_SET_ATTR_INT_GLOBAL("isofs_open_fd_count", open_fd_count > 0 ? open_fd_count - 1 : 0);
// Intentionally do not return fd_obj so the runtime can reclaim it.

// Preconditions: system initialized and fd open
int already_init = FUZZ_GET_ATTR_INT_GLOBAL("isofs_initialized");
if (!already_init) { FUZZ_BAIL(); }
int is_open = FUZZ_GET_ATTR_INT(fd_obj, "open");
int fd = FUZZ_GET_ATTR_INT(fd_obj, "fd");
if (!is_open) { FUZZ_BAIL(); }

