int fd = FUZZ_GET_ATTR_INT(fd_obj, "fd");
if (!is_open) { FUZZ_BAIL(); }

// Generate offset and origin; map origin to common SEEK_* semantics (0,1,2)
u32 offset = *FUZZ_PARAM(u32);
int origin_sel = (int)(*FUZZ_PARAM(unsigned int) % 3);
int origin = origin_sel; // 0: SEEK_SET, 1: SEEK_CUR, 2: SEEK_END (assumed)

int rc = isofs_Seek(fd, offset, origin);
if (rc < 0) { FUZZ_BAIL(); }

// Keep fd alive

