import os
import random
import string
from typing import List

def _rand(r: random.Random, n: int) -> int:
    return r.randrange(n)

def _pick(r: random.Random, items: List[str]) -> str:
    return items[_rand(r, len(items))]

def _weighted_choice(r: random.Random, choices):
    # choices: list of (weight, value)
    total = sum(w for w, _ in choices)
    x = r.uniform(0, total)
    upto = 0.0
    for w, v in choices:
        if upto + w >= x:
            return v
        upto += w
    return choices[-1][1]

def _gen_iso9660_filename(r: random.Random) -> str:
    # Generate ISO9660-ish filename: 1-8 chars, optional extension up to 3 chars, uppercase, digits, underscore
    name_chars = string.ascii_uppercase + string.digits + "_"
    name_len = r.randint(1, 8)
    name = ''.join(r.choice(name_chars) for _ in range(name_len))
    if r.random() < 0.7:
        ext_len = r.randint(1, 3)
        ext = ''.join(r.choice(name_chars) for _ in range(ext_len))
        return f"{name}.{ext}"
    return name

def _gen_joliet_or_udf_filename(r: random.Random) -> str:
    # Longer name, mixed case, may include spaces, dots, dashes, underscores
    name_chars = string.ascii_letters + string.digits + " _.-"
    base_len = r.randint(1, 32)
    base = ''.join(r.choice(name_chars) for _ in range(base_len)).strip()
    # ensure non-empty after strip
    if not base:
        base = "X"
    # optional extension
    if r.random() < 0.6 and '.' not in base:
        ext_len = r.randint(1, 6)
        ext_chars = string.ascii_letters + string.digits
        ext = ''.join(r.choice(ext_chars) for _ in range(ext_len))
        base = f"{base}.{ext}"
    return base

def _gen_ps2_specific_names(r: random.Random) -> List[str]:
    return [
        "SYSTEM.CNF",
        "SLUS_203.12",
        "SCUS_971.02",
        "SLES_500.00",
        "IOPRP280.IMG",
        "IOP\IOPRP280.IMG",
        "VIDEO_TS\VIDEO_TS.IFO",
        "BDMV\index.bdmv",  # non-PS2 but interesting
        "LICENSE.TXT",
        "README",
    ]

def _gen_directory_component(r: random.Random) -> str:
    style = _weighted_choice(r, [
        (3, 'iso'),
        (5, 'joliet'),
    ])
    if style == 'iso':
        return _gen_iso9660_filename(r)
    else:
        return _gen_joliet_or_udf_filename(r)

def _gen_path(r: random.Random) -> str:
    # Generate a path intended for isofs_Open inside an ISO image.
    # We mix absolute-like and relative-like styles, different separators, and special entries.
    sep = _weighted_choice(r, [(8, '/'), (2, '\\')])

    # Sometimes pick a curated interesting path
    curated = _gen_ps2_specific_names(r)
    if r.random() < 0.35:
        return _pick(r, curated)

    parts: List[str] = []

    # Optional leading dot components
    if r.random() < 0.2:
        parts.append('.')
    if r.random() < 0.1:
        parts.append('..')

    # Depth between 1 and 6
    depth = r.randint(1, 6)
    for i in range(depth):
        if r.random() < 0.15:
            parts.append('.')
        elif r.random() < 0.15:
            parts.append('..')
        else:
            parts.append(_gen_directory_component(r))

    path = sep.join(parts)

    # Optionally add trailing separator to test directory handling
    if r.random() < 0.1:
        path = path + sep

    # Optionally normalize multiple separators or add duplicate separators
    if r.random() < 0.1:
        path = path.replace(sep, sep * 2)

    return path

def _encode_path(path: str, r: random.Random) -> bytes:
    # Majority ASCII/UTF-8, sometimes include arbitrary bytes to simulate raw path bytes
    if r.random() < 0.85:
        data = path.encode('utf-8', errors='ignore')
    else:
        # inject some non-ASCII bytes
        b = bytearray(path.encode('utf-8', errors='ignore'))
        for _ in range(r.randint(1, min(5, max(1, len(b))))):
            pos = r.randrange(len(b)) if b else 0
            val = r.randrange(0x80, 0x100)
            if b:
                b[pos] = val
            else:
                b.append(val)
        data = bytes(b)
    # Ensure non-empty and within 4096
    if not data:
        data = b"X"
    return data[:4096]

def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Build a mix of candidate paths to increase coverage when the harness reuses the same buffer
    # but typically FUZZ_PARAM_STR consumes the entire buffer; we'll provide a single path per call.
    path = _gen_path(r)

    # With small probability, prepend or append NUL to test C-string handling (ignored by FUZZ runtime if it uses size)
    if r.random() < 0.05:
        path = path + "\x00"
    if r.random() < 0.05:
        path = "\x00" + path

    return _encode_path(path, r)

import random
import struct
import itertools

# Generator for an arbitrary binary data buffer size probe
# The fuzzer stub only inspects the size (cap) of FUZZ_PARAM_STR() and chooses n in [1, min(cap, 2048)-1] (or 1 if mod becomes 0).
# Our goal: provide varied, interesting sizes to exercise read sizes around boundaries while remaining valid arbitrary data.

_MAX_SIZE = 4096

def _sizes_of_interest(rng: random.Random):
    # Include classic boundaries and ISO-relevant sizes.
    base = [
        0, 1, 2, 3, 7, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 511, 512,
        1023, 1024, 1536, 1792, 1920, 1979, 2000, 2047, 2048, 2049, 2050,
        3072, 3584, 3840, 4095, 4096
    ]
    # Filter to max
    base = [s for s in base if s <= _MAX_SIZE]
    # Add a few random sizes in [1, 4096]
    for _ in range(8):
        base.append(rng.randint(1, _MAX_SIZE))
    # Shuffle to vary
    rng.shuffle(base)
    return base

def _pattern_bytes(length: int, rng: random.Random) -> bytes:
    if length <= 0:
        return b""  # Will cause FUZZ_BAIL; avoid by ensuring non-zero sizes in selection

    # Choose among multiple content patterns; content does not matter, but diversity helps downstream behaviors.
    choice = rng.randint(0, 4)
    if choice == 0:
        # Repeating alphabet
        seq = (bytes((ord('A') + (i % 26),)) for i in range(length))
        return b"".join(seq)
    elif choice == 1:
        # Incrementing bytes
        return bytes((i % 256 for i in range(length)))
    elif choice == 2:
        # Pseudorandom but seeded deterministically per call
        return bytes(rng.getrandbits(8) for _ in range(length))
    elif choice == 3:
        # All 0x00 except some markers every 512 bytes
        b = bytearray(length)
        for i in range(0, length, 512):
            b[i] = 0x5A
        return bytes(b)
    else:
        # All 0xFF with a footer
        b = bytearray(b"\xFF" * length)
        if length >= 4:
            b[-4:] = b"CAP\0"
        return bytes(b)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # The stub bails if cap == 0, so ensure we produce non-empty buffers.
    # Pick a size from a curated list. If 0 is drawn, choose next non-zero.
    sizes = _sizes_of_interest(rng)
    size = None
    for s in sizes:
        if s > 0:
            size = s
            break
    if size is None:
        size = 1

    # Ensure we are not exceeding the performance cap; size can be up to 4096 as allowed.
    size = max(1, min(size, _MAX_SIZE))

    # Build the buffer content.
    data = _pattern_bytes(size, rng)

    # Guarantee length exactly as chosen.
    if len(data) != size:
        if len(data) > size:
            data = data[:size]
        else:
            data = data + b"\x00" * (size - len(data))

    return data
